import os
import csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190124", "20190125", "20190126"]
targets = ["冀宁线", "西气东输一线"]

total = {t: 0.0 for t in targets}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    day = {t: 0.0 for t in targets}
    with open(p, encoding="utf-8") as f:
        for row in csv.DictReader(f):
            name = row["管道划分"]
            if name in targets:
                day[name] += float(row["管道流量"])
    for t in targets:
        total[t] += day[t]
    print(d, {t: round(day[t], 3) for t in targets})

for t in targets:
    print(t, round(total[t], 3))

diff = total["冀宁线"] - total["西气东输一线"]
print("diff_jining_minus_west_east", round(diff, 3))
print("higher", "冀宁线" if diff > 0 else "西气东输一线")

