import os
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190127", "20190128"]
pipelines = {"冀宁线", "川气东送"}

rows = {}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    with open(p, encoding="utf-8") as f:
        header = f.readline().strip().split(",")
        for line in f:
            parts = line.strip().split(",")
            rec = dict(zip(header, parts))
            if rec["管道划分"] in pipelines:
                key = (rec["起点站名"], rec["终点站名"], rec["管道划分"])
                flow = float(rec["管道流量"])
                rows.setdefault(key, []).append((d, flow))

from collections import defaultdict
seg_by_pipe = defaultdict(list)
for (s, e, pipe), vals in sorted(rows.items()):
    zero_days = [d for d, f in vals if abs(f) == 0]
    seg_by_pipe[pipe].append((s, e, len(zero_days), [d for d, f in vals if abs(f) == 0]))

for pipe in pipelines:
    print(f"=== {pipe} ===")
    total_days = len(dates)
    for s, e, zc, zd in seg_by_pipe[pipe]:
        print(f"{s}->{e}: zero_days={zc}/{total_days} ratio={zc/total_days:.2f} zero_dates={zd}")

# top-3 segments with most zero days across both pipelines
all_segs = []
for pipe in pipelines:
    for s, e, zc, zd in seg_by_pipe[pipe]:
        all_segs.append((zc, pipe, s, e))
all_segs.sort(key=lambda x: (-x[0], x[1], x[2]))
print("=== TOP segments by zero_days ===")
for zc, pipe, s, e in all_segs[:3]:
    print(f"{pipe} {s}->{e}: zero_days={zc}")

