            start, end, typ, pipe, flow = parts
            for t in targets:
                if pipe == t[0] and start == t[1] and end == t[2]:
                    v = float(flow)
                    totals[t] += v
                    daily[t].append((d, v))

for t in targets:
    print(t, "daily:", daily[t])
    print(t, "total:", totals[t])

diff = totals[targets[0]] - totals[targets[1]]
print("diff (陕京二线 - 冀宁线):", diff)

