import os
from pathlib import Path
from collections import deque

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
csv_path = DIR / "20190114_pipeline.csv"

edges = []
with open(csv_path, encoding="utf-8-sig") as f:
    header = f.readline().strip().split(",")
    for line in f:
        parts = line.strip().split(",")
        if len(parts) < 3:
            continue
        row = dict(zip(header, parts))
        src = row.get("source_station") or row.get("source") or parts[0]
        tgt = row.get("target_station") or row.get("target") or parts[1]
        pipe = row.get("pipeline_name") or row.get("pipeline") or ""
        edges.append((src.strip(), tgt.strip(), pipe.strip()))

print("HEADER:", header)
print("EDGE_COUNT:", len(edges))
print("SAMPLE:", edges[:3])

adj = {}
for s, t, p in edges:
    adj.setdefault(s, []).append((t, p))

def shortest_path(start, goal):
    q = deque([(start, [])])
    seen = {start}
    while q:
        node, path = q.popleft()
        for nxt, pipe in adj.get(node, []):
            if nxt in seen:
                continue
            new_path = path + [(node, nxt, pipe)]
            if nxt == goal:
                return new_path
            seen.add(nxt)
            q.append((nxt, new_path))
    return None

for src in ["榆林站", "靖边站"]:
    p = shortest_path(src, "南通站")
    print("PATH", src, "-> 南通站:")
    if p is None:
        print("  NO PATH")
    else:
        print("  HOPS:", len(p))
        for s, t, pipe in p:
            print("  ", s, "->", t, "via", pipe)

